require_once __DIR__.'/db.php'; require_once __DIR__.'/../includes/auth.php'; requireAdmin(); header('Content-Type: application/json; charset=UTF-8');$type=$_GET['type']??'volunteers';$table=$type==='trainers'?'trainers':'volunteers';$method=$_SERVER['REQUEST_METHOD'];
if($method==='GET'){$r=$conn->query("SELECT x.*,p.name program_name FROM `$table` x LEFT JOIN programs p ON p.id=x.program_id ORDER BY x.id DESC");$rows=[];while($x=$r->fetch_assoc())$rows[]=$x;echo json_encode(['success'=>true,'items'=>$rows],JSON_UNESCAPED_UNICODE);exit;}
$d=json_decode(file_get_contents('php://input'),true)??[];if($method==='POST'){$name=trim($d['name']??'');$phone=trim($d['phone']??'');$program=(int)($d['program_id']??0);if($table==='trainers'){$specialty=trim($d['specialty']??'');$st=$conn->prepare('INSERT INTO trainers(name,phone,specialty,program_id) VALUES(?,?,?,NULLIF(?,0))');$st->bind_param('sssi',$name,$phone,$specialty,$program);}else{$role=trim($d['role']??'');$st=$conn->prepare('INSERT INTO volunteers(name,phone,role,program_id) VALUES(?,?,?,NULLIF(?,0))');$st->bind_param('sssi',$name,$phone,$role,$program);}$st->execute();echo json_encode(['success'=>true,'message'=>'تمت الإضافة'],JSON_UNESCAPED_UNICODE);exit;}if($method==='DELETE'){$id=(int)($_GET['id']??0);$st=$conn->prepare("DELETE FROM `$table` WHERE id=?");$st->bind_param('i',$id);$st->execute();echo json_encode(['success'=>true,'message'=>'تم الحذف'],JSON_UNESCAPED_UNICODE);exit;}
